// n8n сам на sudrf не ходит. Два режима одного вебхука «Дело»:
// 1) справка с сайта: website + topic (hours|contacts|structure|jurisdiction|duty|visitors|general)
// 2) карточка дела: court_slug (6 Воронеж) + case_number|last_name
const API_BASE = 'http://77.222.55.230:8080';
const API_KEY = 'SET_COURT_KB_API_KEY';

const COURTS = {
  'sovetsky-vrn': true,
  'kominternovsky-vrn': true,
  'zheleznodorozhny-vrn': true,
  'levoberezhny-vrn': true,
  'centralny-vrn': true,
  'lensud-vrn': true,
};

const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const court_slug = String(body.court_slug || '').trim();
const normalizeCaseNumber = (raw) => {
  // Стандарт: 2-1248/2026. Отрезаем «ДЕЛО №», хвост ~ М-…, нормализуем тире.
  let t = String(raw || '').trim();
  if (!t) return '';
  const prefix = /^(?:дело|дел[ауо]?|case|№|N[oо]?\.?|number)\s*/iu;
  t = t.replace(prefix, '').trim();
  t = t.replace(prefix, '').trim();
  for (const sep of ['~', '～', '≈']) {
    if (t.includes(sep)) { t = t.split(sep)[0].trim(); break; }
  }
  t = t.replace(/\s+[МмMm]\s*[-–—−]?\s*\d+(?:\/\d+)?\s*$/u, '').trim();
  t = t.replace(/[–—−‐‑]/g, '-');
  t = t.replace(/\s+/g, ' ').trim();
  t = t.replace(/\s*-\s*/g, '-').replace(/\s*\/\s*/g, '/');
  const re = /^(\d{1,4}[а-яА-ЯёЁa-zA-Z]?)-(\d{1,7}[а-яА-ЯёЁa-zA-Z]?)(?:\/(\d{4}))?$/u;
  let m = t.match(re);
  if (!m) {
    const extract = /(\d{1,4}[а-яА-ЯёЁa-zA-Z]?)\s*[-–—−]\s*(\d{1,7}[а-яА-ЯёЁa-zA-Z]?)\s*(?:\/\s*(\d{4}))?/u;
    const em = t.match(extract);
    if (!em) return '';
    t = em[1] + '-' + em[2] + (em[3] ? '/' + em[3] : '');
    m = t.match(re);
    if (!m) return '';
  }
  const fold = (p) => {
    if (p.length >= 2 && /[AaА]/.test(p.slice(-1))) return p.slice(0, -1) + 'а';
    return p;
  };
  return fold(m[1]) + '-' + fold(m[2]) + (m[3] ? '/' + m[3] : '');
};
const case_number = normalizeCaseNumber(body.case_number);
const last_name = String(body.last_name || '').trim();
const website = String(body.website || body.site || body.sudrf_domain || '').trim();
const topic = String(body.topic || '').trim();
const mode = String(body.mode || '').trim().toLowerCase();
const production_type = String(body.production_type || 'civil_first_instance').trim();

const wantsInfo = mode === 'info' || mode === 'spravka' || mode === 'site'
  || (website && !case_number && !last_name)
  || (website && topic && topic.toLowerCase() !== 'case' && topic.toLowerCase() !== 'дело');

if (wantsInfo) {
  if (!website) {
    return [{ json: { skipHttp: true, status: 'error', result: 'Для справки с сайта нужен website (поле САЙТ из Базы Знаний).' } }];
  }
  return [{ json: {
    skipHttp: false,
    apiUrl: API_BASE + '/delo',
    apiKey: API_KEY,
    payload: {
      mode: 'info',
      website,
      topic: topic || 'hours',
      court_slug: court_slug || null,
      case_number: null,
      last_name: null,
    },
  } }];
}

if (!court_slug || !COURTS[court_slug]) {
  if (website) {
    return [{ json: {
      skipHttp: false,
      apiUrl: API_BASE + '/delo',
      apiKey: API_KEY,
      payload: { mode: 'info', website, topic: topic || 'hours' },
    } }];
  }
  return [{ json: { skipHttp: true, status: 'error', result: `Живая карточка дела только для: ${Object.keys(COURTS).join(', ')}. Для режима/контактов передайте website из БЗ.` } }];
}
if (!case_number && !last_name) {
  return [{ json: { skipHttp: true, status: 'error', result: 'Нужно указать case_number или last_name (либо website+topic для справки).' } }];
}

return [{ json: {
  skipHttp: false,
  apiUrl: API_BASE + '/delo',
  apiKey: API_KEY,
  payload: {
    mode: 'case',
    court_slug,
    case_number: case_number || null,
    last_name: last_name || null,
    production_type,
  },
} }];

const item = $input.first().json || {};
const nested = item.body && typeof item.body === 'object' ? item.body : item;
const status = nested.status || item.status;
const result = nested.result || item.result;
if (status && result) {
  return [{ json: { status, result } }];
}
if (nested.detail) {
  return [{ json: { status: 'error', result: String(nested.detail) } }];
}
const err = item.error && (item.error.message || item.error);
if (err) {
  return [{ json: { status: 'error', result: 'Сервис поиска временно недоступен (' + String(err) + '). Попробуйте ещё раз.' } }];
}
return [{ json: { status: 'error', result: 'Сервис поиска временно недоступен. Попробуйте задать вопрос ещё раз.' } }];
